// For loop. Fibonacci numbers
const n = 25;

begin
  var a := 1;
  var b := 1;
  writeln('Fibonacci numbers:');
  write(a,' ',b,' ');

  for var i:=3 to n do
  begin
    var c := a + b;
    write(c,' ');
    a := b;
    b := c;
  end;
end.

// For loop. Maximum of input numbers
const n = 10;

var max: real;

begin
  writelnFormat('Enter {0} numbers',n);
  max := integer.MinValue; // smallest integer number
  for var i:=1 to n do
  begin
