    read(x);
    if x>max then
      max := x;
  end;  
  writeln('Maximum is ',max);
end.

// For loop. Value search. Break operator
const n = 10;

var 
  k: integer;
  found: boolean;

begin
  writeln('Enter number to search: ');
  readln(k);
  writelnFormat('Enter {0} numbers',n);
  found := False;
  for var i:=1 to n do
  begin
    var x: integer;
    read(x);
    if x=k then
    begin
      found := True;
      break;
    end;
  end;
  if found then
    writeln('Found')
  else writeln('Not found');  
end.

